LEGACY_RECORDS = [{'source': '/Users/cora/Documents/GitHub/lean-llm-opt/redundancy_complete/50pct/S1/Large-scale-or/RA_testing/RA10/SalesOfASupermarket1/capacity.csv', 'values': {'SectionID': '1', 'archive_revision_number': '3', 'Capacity': '100'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/redundancy_complete/50pct/S1/Large-scale-or/RA_testing/RA10/SalesOfASupermarket1/capacity.csv', 'values': {'SectionID': '2', 'archive_revision_number': '7', 'Capacity': '150'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/redundancy_complete/50pct/S1/Large-scale-or/RA_testing/RA10/SalesOfASupermarket1/capacity.csv', 'values': {'SectionID': '3', 'archive_revision_number': '3', 'Capacity': '120'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/redundancy_complete/50pct/S1/Large-scale-or/RA_testing/RA10/SalesOfASupermarket1/capacity.csv', 'values': {'SectionID': '4', 'archive_revision_number': '4', 'Capacity': '130'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/redundancy_complete/50pct/S1/Large-scale-or/RA_testing/RA10/SalesOfASupermarket1/capacity.csv', 'values': {'SectionID': '5', 'archive_revision_number': '6', 'Capacity': '90'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/redundancy_complete/50pct/S1/Large-scale-or/RA_testing/RA10/SalesOfASupermarket1/capacity.csv', 'values': {'SectionID': '6', 'archive_revision_number': '4', 'Capacity': '110'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/redundancy_complete/50pct/S1/Large-scale-or/RA_testing/RA10/SalesOfASupermarket1/capacity.csv', 'values': {'SectionID': '7', 'archive_revision_number': '3', 'Capacity': '160'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/redundancy_complete/50pct/S1/Large-scale-or/RA_testing/RA10/SalesOfASupermarket1/capacity.csv', 'values': {'SectionID': '8', 'archive_revision_number': '8', 'Capacity': '140'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/redundancy_complete/50pct/S1/Large-scale-or/RA_testing/RA10/SalesOfASupermarket1/products.csv', 'values': {'record_keeper_group': 'Team B', 'ProductName': '1', 'Value': '10', 'archive_revision_number': '1', 'Weight': '2'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/redundancy_complete/50pct/S1/Large-scale-or/RA_testing/RA10/SalesOfASupermarket1/products.csv', 'values': {'record_keeper_group': 'Team A', 'ProductName': '2', 'Value': '15', 'archive_revision_number': '4', 'Weight': '3'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/redundancy_complete/50pct/S1/Large-scale-or/RA_testing/RA10/SalesOfASupermarket1/products.csv', 'values': {'record_keeper_group': 'Team C', 'ProductName': '3', 'Value': '8', 'archive_revision_number': '2', 'Weight': '1'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/redundancy_complete/50pct/S1/Large-scale-or/RA_testing/RA10/SalesOfASupermarket1/products.csv', 'values': {'record_keeper_group': 'Team A', 'ProductName': '4', 'Value': '12', 'archive_revision_number': '9', 'Weight': '2'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/redundancy_complete/50pct/S1/Large-scale-or/RA_testing/RA10/SalesOfASupermarket1/products.csv', 'values': {'record_keeper_group': 'Team A', 'ProductName': '5', 'Value': '20', 'archive_revision_number': '3', 'Weight': '4'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/redundancy_complete/50pct/S1/Large-scale-or/RA_testing/RA10/SalesOfASupermarket1/products.csv', 'values': {'record_keeper_group': 'Team C', 'ProductName': '6', 'Value': '25', 'archive_revision_number': '7', 'Weight': '5'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/redundancy_complete/50pct/S1/Large-scale-or/RA_testing/RA10/SalesOfASupermarket1/products.csv', 'values': {'record_keeper_group': 'Team A', 'ProductName': '7', 'Value': '5', 'archive_revision_number': '2', 'Weight': '1'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/redundancy_complete/50pct/S1/Large-scale-or/RA_testing/RA10/SalesOfASupermarket1/products.csv', 'values': {'record_keeper_group': 'Team C', 'ProductName': '8', 'Value': '30', 'archive_revision_number': '3', 'Weight': '6'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/redundancy_complete/50pct/S1/Large-scale-or/RA_testing/RA10/SalesOfASupermarket1/products.csv', 'values': {'record_keeper_group': 'Team C', 'ProductName': '9', 'Value': '18', 'archive_revision_number': '7', 'Weight': '3'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/redundancy_complete/50pct/S1/Large-scale-or/RA_testing/RA10/SalesOfASupermarket1/products.csv', 'values': {'record_keeper_group': 'Team A', 'ProductName': '10', 'Value': '22', 'archive_revision_number': '5', 'Weight': '4'}}]
import gurobipy as gp
from gurobipy import GRB
capacity_records = [r for r in LEGACY_RECORDS if r['source'].endswith('capacity.csv')]
section_ids = []
section_capacities = {}
for rec in capacity_records:
    sid = str(rec['values']['SectionID'])
    section_ids.append(sid)
    section_capacities[sid] = int(rec['values']['Capacity'])
product_records = [r for r in LEGACY_RECORDS if r['source'].endswith('products.csv')]
product_ids = []
product_values = {}
product_weights = {}
for rec in product_records:
    pid = str(rec['values']['ProductName'])
    product_ids.append(pid)
    product_values[pid] = int(rec['values']['Value'])
    product_weights[pid] = int(rec['values']['Weight'])
if len(section_ids) == 0 or len(product_ids) == 0:
    raise ValueError('Missing section or product data.')
for sid in section_ids:
    if sid not in section_capacities:
        raise ValueError(f'Missing capacity for section {sid}')
for pid in product_ids:
    if pid not in product_values or pid not in product_weights:
        raise ValueError(f'Missing value or weight for product {pid}')
m = gp.Model('Supermarket_Section_Allocation')
x_vars = m.addVars(section_ids, product_ids, lb=0, vtype=GRB.INTEGER, name='')
m.setObjective(gp.quicksum((product_values[pid] * x_vars[sid, pid] for sid in section_ids for pid in product_ids)), GRB.MAXIMIZE)
m.addConstrs((gp.quicksum((product_weights[pid] * x_vars[sid, pid] for pid in product_ids)) <= section_capacities[sid] for sid in section_ids), name='')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for var in m.getVars():
        print(f'{var.VarName}: {var.X}')
else:
    print(f'Solver status: {m.Status}')